package com.wiseway.web;
import com.wiseway.api.ApiDtos.*; import com.wiseway.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController { private final RecommendationService rec; private final SavedRouteService routes; private final ExpenseService expenses; private final GeocodingService geocoding; public ApiController(RecommendationService r,SavedRouteService s,ExpenseService e,GeocodingService g){rec=r;routes=s;expenses=e;geocoding=g;}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP","application","WiseWay");}
 @GetMapping("/locations/search") public List<LocationResponse> locations(@RequestParam String q){return geocoding.search(q).stream().map(x->new LocationResponse(x.id(),x.name(),x.context(),x.latitude(),x.longitude())).toList();}
 @PostMapping("/recommendations/compare") public CompareResponse compare(@Valid @RequestBody CompareRequest r){return rec.compare(r,Set.of());}
 @PostMapping("/recommendations/plan-b") public PlanBResponse planB(@Valid @RequestBody PlanBRequest r){return rec.planB(r);}
 @GetMapping("/saved-routes") public List<RouteResponse> routes(){return routes.list();} @GetMapping("/saved-routes/{id}") public RouteResponse route(@PathVariable Long id){return routes.get(id);} @PostMapping("/saved-routes") public ResponseEntity<RouteResponse> createRoute(@Valid @RequestBody RouteRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(routes.create(r));} @PutMapping("/saved-routes/{id}") public RouteResponse updateRoute(@PathVariable Long id,@Valid @RequestBody RouteRequest r){return routes.update(id,r);} @DeleteMapping("/saved-routes/{id}") public ResponseEntity<Void> deleteRoute(@PathVariable Long id){routes.delete(id);return ResponseEntity.noContent().build();}
 @GetMapping("/journey-logs") public List<ExpenseResponse> logs(@RequestParam(required=false) LocalDate from,@RequestParam(required=false) LocalDate to){return expenses.list(from,to);} @PostMapping("/journey-logs") public ResponseEntity<ExpenseResponse> createLog(@Valid @RequestBody ExpenseRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(expenses.create(r));} @DeleteMapping("/journey-logs/{id}") public ResponseEntity<Void> deleteLog(@PathVariable Long id){expenses.delete(id);return ResponseEntity.noContent().build();} @GetMapping("/expenses/summary") public Summary summary(@RequestParam LocalDate from,@RequestParam LocalDate to,@RequestParam(defaultValue="DAY") String groupBy){return expenses.summary(from,to,groupBy);}
}
